  R=[rx("Calcula √5 · √20.", "√5·√20", "10", "√5 · √20 = √100 = 10."),
     rx("Calcula 3√7 + 2√7.", "3√7+2√7", "5√7", "Son raíces semejantes: 3 + 2 = 5 veces √7."),
     rx("Calcula (√9)² usando la propiedad (√a)² = a.", "(√9)²", "9", "Elevar al cuadrado una raíz cuadrada devuelve el radicando.")],
  C=[rx("Calcula √72 ÷ √2.", "√72/√2", "6", "√72 ÷ √2 = √36 = 6."),
     ex("¿Cuál expresión es igual a 4√3 + √3? A) 5√3 B) 4√6", "A", "Es 4 + 1 = 5 veces √3; sumar raíces no cambia el radicando."),
     rx("Calcula (2√5)².", "(2√5)²", "20", "(2√5)² = 2² · (√5)² = 4 · 5 = 20.")],
  A=[rx("Calcula √12 + √75.", "√12+√75", "7√3", "√12 = 2√3 y √75 = 5√3, y 2 + 5 = 7."),
     rx("Calcula (3√2)(2√6).", "(3√2)(2√6)", "12√3", "3 · 2 = 6 y √2 · √6 = √12 = 2√3; entonces 6 · 2√3 = 12√3."),
     rx("Calcula √98 − √8.", "√98-√8", "5√2", "√98 = 7√2 y √8 = 2√2, y 7 − 2 = 5.")],
